from pathlib import Path


def read_public(root: Path, user_path: str) -> str:
    root = root.resolve()
    resolved = (root / user_path).resolve()
    if not resolved.is_relative_to(root):
        raise ValueError("user path escapes the public root")
    return resolved.read_text(encoding="utf8")

